<section class="dashboard-content"><div class="dashboard-heading"><div><div class="eyebrow">مرکز اطلاع‌رسانی</div><h1>اعلان‌ها</h1></div><form method="post" action="<?=url('/notifications/read-all')?>"><?=csrf_field()?><button class="button button-small">خواندن همه</button></form></div><section class="dash-card"><?php foreach($notifications as $n):?><article class="proposal-row <?= $n['read_at']?'':'unread' ?>"><div><strong><?=e($n['title'])?></strong><p><?=e($n['body']??'')?></p><small><?=e($n['created_at'])?></small></div><?php if(!$n['read_at']):?><form method="post" action="<?=url('/notifications/read')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($n['id'])?>"><button class="action-button" type="submit">خواندم</button></form><?php endif;?></article><?php endforeach;?><?php if(!$notifications):?><div class="empty-state">اعلان جدیدی ندارید.</div><?php endif;?></section></section>